public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Flatten the paths array to a list of all adjacent nodes for quick lookup
    List<Integer>[] adjacentNodes = new List[n * n];
    for (int[] path : paths) {
        adjacentNodes[path[0] * n + path[1]] = new ArrayList<>();
        adjacentNodes[path[0] * n + path[1]].add(path[2] * n + path[3]);
        adjacentNodes[path[2] * n + path[3]].add(path[0] * n + path[1]);
    }

    // Use Depth-First Search (DFS) to check if one can reach the end from the start
    boolean[] visited = new boolean[n * n];
    Stack<Integer> stack = new Stack<>();

    stack.push(start[0] * n + start[1]);
    visited[start[0] * n + start[1]] = true;

    while (!stack.isEmpty()) {
        int current = stack.pop();

        if (current == end[0] * n + end[1]) {
            return "can be travelled";
        }

        for (int next : adjacentNodes[current]) {
            if (!visited[next]) {
                stack.push(next);
                visited[next] = true;
            }
        }
    }

    return "cannot be travelled";
}

