    // Sort the array to find the median
    Arrays.sort(arr);

    // Calculate the number of elements to remove (5% of the array size)
    int countToRemove = (int) (arr.length * 0.05);

    // Remove the smallest and largest countToRemove elements
    int[] trimmedArr = Arrays.stream(arr).skip(countToRemove).limit(arr.length - countToRemove).toArray();

    // Calculate the mean of the remaining elements
    double sum = Arrays.stream(trimmedArr).sum();
    return sum / trimmedArr.length;
