    for (int i = 0; i < n; i++) {
        if (dp[i] > 2 && !hasApple[i]) {
            dp[i] = dp[i] - 2; // Subtract 2 if the node has no apple
        }
    }

    return dp[0]; // Return the minimum time to reach node 0
}

