public boolean splitArraySameAverage(int[] nums) {
    int sum = 0, n = nums.length;
    // Calculate the sum of array elements
    for (int num : nums) {
        sum += num;
    }

    // If the total sum is odd, it cannot be split into two equal averages
    if (sum % 2 == 1) {
        return false;
    }

    int targetAverage = sum / 2;
    // Traverse all possible subarray sums
    for (int i = 1; i <= n - 1; i++) {
        // Check if the sum of the first i elements can be equal to the target average
        if (sum == targetAverage * (i - 1)) {
            // Check if the remaining sum can be split into two equal halves
            return canSplit(nums, i, targetAverage * (n - i));
        }
    }
    return false;
}

