public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    int minCost1 = cost[0];
    int minCost2 = cost[1];
    for (int i = 2; i < n; i++) {
        int temp = minCost1;
        minCost1 = Math.min(minCost1 + cost[i], minCost2 + cost[i]);
        minCost2 = temp;
    }
    return Math.min(minCost1, minCost2);
}

