public int minCostClimbingStairs(int[] cost) {
    // Reduce time complexity from O(n^2) to O(n)
    // Initialize first two costs
    int f1 = cost[0], f2 = cost[1], f3 = Math.min(f1, f2);
    // Iterate through cost array
    for (int i = 2; i < cost.length; i++) {
        // Update f3 with the minimum of adjacent elements plus the current cost
        f3 = Math.min(f1 + cost[i], f2 + cost[i]);
        // Update f1 and f2 to be previous f3 values for next iteration
        f1 = f2;
        f2 = f3;
    }
    // Return the minimum cost from the last two steps
    return Math.min(f1, f2);
}

