public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int unique = (1 << k);
    boolean[] found = new boolean[unique];
    for (int i = 0; i <= n - k; i++) {
        int num = Integer.parseInt(s.substring(i, i + k), 2);
        if (!found[num]) {
            found[num] = true;
            unique--;
        }
        if (unique == 0) {
            return true;
        }
    }
    return false;
}

