            if (lastDigit != 9) {
                int bigger = num * 10 + lastDigit + 1;
                if (bigger >= low && bigger <= high) {
                    queue.offer(bigger);
                }
            }
        }

        result.sort(Integer::compareTo);
        return result;
    }

