public static String addThousandSeparator(int n) {
    if (n == 0) return "0";
    StringBuilder sb = new StringBuilder();
    boolean addDot = false;
    while (n > 0) {
        int remainder = n % 10;
        if (addDot) {
            sb.insert(0, ".");
        }
        sb.insert(0, remainder);
        n /= 10;
        addDot = true;
    }
    return sb.toString();
}

