public static String addThousandSeparator(int n) {
    if (n == 0) return "0";

    String numStr = Integer.toString(Math.abs(n));
    StringBuilder sb = new StringBuilder(numStr.length());
    int index = 0;

    for (int i = numStr.length() - 1; i >= 0; i--) {
        sb.append(numStr.charAt(i));
        index++;
        if (index % 3 == 0 && i != 0) {
            sb.append('.');
        }
    }

    return sb.reverse().toString();
}

