public static int findSmallestInteger(int n) {
    String digits = Integer.toString(n);
    char[] arr = digits.toCharArray();

    // sort the array in ascending order
    Arrays.sort(arr);

    // loop through the sorted array to find the smallest integer
    for (int i = arr.length - 2; i >= 0; i--) {
        if (arr[i] < arr[i + 1]) {
            // swap arr[i] and arr[i+1]
            char temp = arr[i];
            arr[i] = arr[i + 1];
            arr[i + 1] = temp;

            // sort the rest of the array in ascending order
            Arrays.sort(arr, i + 1, arr.length);

            // convert the array back to an integer
            return Integer.parseInt(new String(arr));
        }
    }

    // return -1 if not possible to form a larger integer
    return -1;
}

