public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int length = digits.length;
    for (int i = length - 1; i > 0; i--) {
        for (int j = i - 1; j >= 0; j--) {
            if (digits[i] < digits[j]) {
                // Swap digits
                char temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;
                // Form the smallest number by sorting the remaining part
                Arrays.sort(digits, j + 1, length);
                long result = Long.parseLong(String.valueOf(digits));
                if (result > n) {
                    return (int) result;
                }
            }
        }
    }
    return -1;
