public static int minPerfectSquareSum(int n) {
    // Check if the number is a perfect square
    int root = (int) Math.sqrt(n);
    if (root * root == n) {
        return 1;
    }

    int minSquares = n;
    for (int i = 1; i <= root; i++) {
        int square = i * i;
        int remaining = n - square;
        minSquares = Math.min(minSquares, 1 + minPerfectSquareSum(remaining));
    }

    return minSquares;
}

